package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.Order;
import com.bank.payments.domain.port.OrderRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;

/** JDBC adapter of the OrderRepository port (legacy file ORDENES). */
@Repository
public class JdbcOrderRepository implements OrderRepository {

    private static final RowMapper<Order> ORDER_MAPPER = (rs, rowNum) -> {
        long movement = rs.getLong("movement_number");
        Long movementNumber = rs.wasNull() ? null : movement;
        BigDecimal commission = rs.getBigDecimal("commission");
        return new Order(
                rs.getInt("order_number"),
                rs.getInt("company_id"),
                rs.getString("status"),
                rs.getBigDecimal("order_value"),
                movementNumber,
                commission);
    };

    private final JdbcTemplate jdbcTemplate;

    public JdbcOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<Order> findByKey(Integer orderNumber, Integer companyId) {
        List<Order> rows = jdbcTemplate.query(
                "SELECT order_number, company_id, status, order_value, movement_number, commission "
                        + "FROM orders WHERE order_number = ? AND company_id = ? FOR UPDATE",
                ORDER_MAPPER,
                orderNumber, companyId);
        return rows.stream().findFirst();
    }

    @Override
    public void markPaid(Integer orderNumber, Integer companyId, Long movementNumber, BigDecimal commission) {
        jdbcTemplate.update(
                "UPDATE orders SET status = 'G', movement_number = ?, commission = ? "
                        + "WHERE order_number = ? AND company_id = ?",
                movementNumber, commission, orderNumber, companyId);
    }
}
